command:
timeout 110 bash -c 'CREW_DATA_DIR=./data/w1-proof node --input-type=module - <<'"'"'W1_READ'"'"'
import {startServer,createContext,load} from '"'"'./scripts/acceptance-runtime.mjs'"'"';
import {restart,remount} from '"'"'./scripts/checks/work-issues.mjs'"'"';
const server=await startServer();const checks=[];
try{const ids=await load('"'"'issue-proof-state.json'"'"');const ctx=createContext(server.url,ids,checks,{readOnly:true});await restart(ctx);await remount(ctx);console.log(JSON.stringify({mode:'"'"'issue-fresh-remount-read-only'"'"',checks,ok:true}));}
finally{await server.stop();}
W1_READ'

